package org.emulationstation.frontend.netplay;import android.content.*;import org.json.*;import org.emulationstation.frontend.station.*;import java.util.*;import java.util.concurrent.*;public class StationOnlineClient{public static final List<String> calls=Collections.synchronizedList(new ArrayList<>());public static volatile String room="0123456789abcdef0123456789abcdef";public static volatile CountDownLatch ticketEntered,ticketRelease;public StationOnlineClient(Context c){}public static JSONObject command(String s){return new JSONObject().put("command",s);}public JSONObject call(JSONObject r,boolean b,StationApi.Cancellation c)throws Exception{String command=r.getString("command");calls.add(command);if(command.equals("resume-relay")){if(ticketEntered!=null)ticketEntered.countDown();if(ticketRelease!=null&&!ticketRelease.await(4,TimeUnit.SECONDS))throw new Exception("fixture timeout");}return new JSONObject().put("room",new JSONObject().put("roomId",room).put("generation",3).put("relay",new JSONObject().put("protocol","station-stream.v2").put("expiresInSeconds",60).put("ticket","fixture-ticket").put("requestProof","fixture-proof").put("windowBytes",4096)));}public static long count(String s){synchronized(calls){return calls.stream().filter(s::equals).count();}}}
